import { useCallback, useEffect, useMemo, useRef, useState, useSyncExternalStore, type KeyboardEvent } from 'react'
import {
  buildTimeline, deriveAttention, deriveNow, laneLines, nowResultUris, textToString,
  type RunData, type Timeline,
} from '../../contracts/projects/triage.ts'
import {
  fetchEvents, fetchReviewResult, fetchRunInputs, fetchWorkerResult, NOT_RECORDED, orNotRecorded, ProjectsApiError, scopedResultPath, scopedReviewPath,
  type RunDetail, type RunScope, type WorkerResult, type WorkflowDefinition,
} from './api.ts'
import { AssignmentPanel } from './Assignment.tsx'
import { NodeDetail } from './NodeDetail.tsx'
import { LanesLine, NowBanner } from './NowBanner.tsx'
import { AppLink, ErrorPanel, LoadingPanel } from './panels.tsx'
import { assignmentPathname, runPathname } from './routes.ts'
import { RunBar, RunHeader } from './RunHeader.tsx'
import { StepStrip } from './StepStrip.tsx'
import { stepRows, withoutGlyph } from './steps.ts'
import { Activity, StepsTable } from './StepsTimeline.tsx'
import { formatAgo, formatClock, formatSpan } from './time.ts'
import { useNow, useTimeReference, useTimeZone } from './useNow.ts'
import { useResource, type ResourceMeta } from './useResource.ts'
import { WorkflowGraph, type GraphNodeView } from './WorkflowGraph.tsx'
import './run.css'

type Tab = 'run' | 'assignment'

type Props = {
  scope: RunScope
  detail: RunDetail
  /** The workflow's current definition, when the workflow list loaded; used only to say whether it changed. */
  current: WorkflowDefinition | null
  selectedNodeId: string | null
  /** The run's view, from the path: the Run view (a node page is part of it) or Assignment. */
  tab: Tab
  refreshToken: number
  /** Ticks while the run page polls live state; the run's events and inputs re-read in the background with it. */
  pollToken?: number
  /** How fresh the polled run detail is, for the live chip. */
  freshness: ResourceMeta
  onNavigate: (pathname: string) => void
  /** Speaks through the page's polite announcer: here only a change of the run's situation (docs/PRD_VIEWER_UX.md 6.4). */
  onAnnounce: (message: string) => void
}

type Highlight = { nodeId: string; quote: string }
type FileFocus = { nodeId: string; path: string }

const TABS: { id: Tab; label: string; testId: string }[] = [
  { id: 'run', label: 'Run', testId: 'tab-run' },
  { id: 'assignment', label: 'Assignment', testId: 'tab-assignment' },
]

// ---- Lane results: immutable per URI, read once for the page's lifetime (docs/PRD_VIEWER_UX.md 7) --------------------

type CachedResult = { status: 'ready'; result: WorkerResult } | { status: 'absent' } | { status: 'failed'; refresh: number }
const RESULT_CACHE_LIMIT = 200
const cachedResults = new Map<string, CachedResult>()
const inflight = new Set<string>()
const resultListeners = new Set<() => void>()
let resultVersion = 0

function settleResult(uri: string, value: CachedResult) {
  cachedResults.delete(uri)
  cachedResults.set(uri, value)
  if (cachedResults.size > RESULT_CACHE_LIMIT) cachedResults.delete(cachedResults.keys().next().value!)
  resultVersion += 1
  resultListeners.forEach(listener => listener())
}

function subscribeResults(listener: () => void) {
  resultListeners.add(listener)
  return () => { resultListeners.delete(listener) }
}

/**
 * The worker and candidate results the Now banner and the lanes line read (`nowResultUris`), fetched once each. A result
 * that answers 404 counts as absent, not as loading; another failure is retried by the next Refresh.
 */
function useRunResults(scope: RunScope, uris: readonly string[], refreshToken: number): { results: ReadonlyMap<string, WorkerResult>; pending: number } {
  const version = useSyncExternalStore(subscribeResults, () => resultVersion, () => resultVersion)
  const key = uris.join('\n')
  useEffect(() => {
    for (const uri of key === '' ? [] : key.split('\n')) {
      const known = cachedResults.get(uri)
      if (inflight.has(uri) || (known && (known.status !== 'failed' || known.refresh === refreshToken))) continue
      const path = scopedResultPath(scope, uri)
      if (path === null) { settleResult(uri, { status: 'absent' }); continue }
      inflight.add(uri)
      fetchWorkerResult(scope, path).then(
        result => settleResult(uri, { status: 'ready', result }),
        (error: unknown) => settleResult(uri, error instanceof ProjectsApiError && error.notFound ? { status: 'absent' } : { status: 'failed', refresh: refreshToken }),
      ).finally(() => inflight.delete(uri))
    }
  }, [scope, key, refreshToken])
  return useMemo(() => {
    const results = new Map<string, WorkerResult>()
    let pending = 0
    for (const uri of key === '' ? [] : key.split('\n')) {
      const known = cachedResults.get(uri)
      if (known?.status === 'ready') results.set(uri, known.result)
      else if (!known) pending += 1
    }
    return { results, pending }
    // `version` re-reads the cache whenever a result settles.
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [key, version])
}

/** The timeline of a run whose events have not loaded yet: every step shows its status, none a time. */
function emptyTimeline(detail: RunDetail): Timeline {
  return { runStart: { at: detail.summary.created_at, source: 'receipt' }, runEnd: null, lastActivity: null, spans: [], markers: [], gaps: [], byNode: new Map(), activity: [] }
}

/**
 * One run (docs/PRD_VIEWER_UX.md 4.2-4.4). The run page: the header, the Now banner with the likely next step, the lanes
 * line, then the Run and Assignment tabs; the Run view holds the fitted graph, the Steps table and Activity. A node page:
 * the one-line run bar, the tabs, the sticky step strip and the node in full width. One clock ticks here while the run can
 * still change; selecting a step moves the focus to its heading, and coming back returns it to the step's row.
 */
export function RunView({ scope, detail, current, selectedNodeId, tab, refreshToken, pollToken = 0, freshness, onNavigate, onAnnounce }: Props) {
  const { summary, definition, snapshot } = detail
  const clock = useNow(summary.status !== 'succeeded' && summary.status !== 'cancelled')
  const [zone] = useTimeZone()
  const runStart = useTimeReference()
  const snapshotById = new Map(snapshot.nodes.map(node => [node.node_id, node]))
  const selectedDefinition = selectedNodeId === null ? null : definition.nodes.find(node => node.node_id === selectedNodeId) ?? null
  const selectedState = selectedNodeId === null ? null : snapshotById.get(selectedNodeId) ?? null

  const runKey = `${scope.projectId}/${scope.workflowId}/${scope.runId}`
  const loadEvents = useCallback((signal: AbortSignal) => fetchEvents(scope, signal), [scope])
  const { state: events, reload: reloadEvents } = useResource(`events:${runKey}`, loadEvents, refreshToken, pollToken)
  // The inputs are one resource per run; a 404 INPUTS_NOT_FOUND means "not recorded", which loads as null.
  const loadInputs = useCallback((signal: AbortSignal) => orNotRecorded(fetchRunInputs(scope, signal), NOT_RECORDED.inputs), [scope])
  const { state: inputs, reload: reloadInputs } = useResource(`inputs:${runKey}`, loadInputs, refreshToken, pollToken)
  // The recorded review is immutable per URI; a run whose export predates reviews has none.
  const reviewUri = snapshot.nodes.find(node => node.node_id === 'review')?.result_uri ?? null
  const reviewPath = reviewUri === null ? null : scopedReviewPath(scope, reviewUri)
  const loadReview = useCallback((signal: AbortSignal) => orNotRecorded(fetchReviewResult(scope, reviewPath!, signal), NOT_RECORDED.review), [scope, reviewPath])
  const { state: review } = useResource(reviewPath === null ? null : `review:${reviewPath}`, loadReview, refreshToken)

  const eventsData = events.status === 'ready' ? events.data : null
  const inputsData = inputs.status === 'ready' ? inputs.data : null
  const reviewData = review.status === 'ready' ? review.data : null
  const uris = useMemo(() => (eventsData === null ? [] : nowResultUris(detail, eventsData)), [detail, eventsData])
  const { results, pending } = useRunResults(scope, uris, refreshToken)
  const run: RunData | null = useMemo(
    () => (eventsData === null ? null : { detail, events: eventsData, inputs: inputsData, review: reviewData, results }),
    [detail, eventsData, inputsData, reviewData, results],
  )
  // The banner waits for what its rules read: the inputs, the review and the lane results (`Now.missing`).
  const settled = run !== null && (inputs.status === 'ready' || inputs.status === 'error') && (reviewPath === null || review.status === 'ready' || review.status === 'error') && pending === 0
  const now = useMemo(() => (settled && run ? deriveNow(run) : null), [settled, run])
  const attention = useMemo(() => (run ? deriveAttention(run) : null), [run])
  const lanes = useMemo(() => (run ? laneLines(run) : []), [run])
  const timeline = run ? buildTimeline(run) : null
  const rows = stepRows(detail, timeline ?? emptyTimeline(detail), { now: clock, attention: attention ?? undefined })
  const labels = useMemo(() => new Map(definition.nodes.map(node => [node.node_id, node.label])), [definition.nodes])
  const graphNodes: GraphNodeView[] = definition.nodes.map(node => {
    const state = snapshotById.get(node.node_id)!
    return { node_id: node.node_id, label: node.label, kind: node.kind, depends_on: node.depends_on, status: state.status, attempt: state.attempt, attention: attention?.nodes.get(node.node_id)?.kind ?? null }
  })

  // A requirement quote handed from a review finding to a worker's task; it applies to one node and is dropped once applied or when leaving it.
  const [pendingHighlight, setPendingHighlight] = useState<Highlight | null>(null)
  const clearHighlight = useCallback(() => setPendingHighlight(null), [])
  const highlight = pendingHighlight !== null && pendingHighlight.nodeId === selectedNodeId ? pendingHighlight.quote : null
  // A captured file handed from a review finding to the launch node that shows it, applied the same way.
  const [pendingFile, setPendingFile] = useState<FileFocus | null>(null)
  const clearFile = useCallback(() => setPendingFile(null), [])
  const fileFocus = pendingFile !== null && pendingFile.nodeId === selectedNodeId ? pendingFile.path : null

  const runHref = runPathname(scope.projectId, scope.workflowId, scope.runId)
  const nodeHref = useCallback((nodeId: string) => runPathname(scope.projectId, scope.workflowId, scope.runId, nodeId), [scope])
  const tabHref = (id: Tab) => (id === 'assignment' ? assignmentPathname(scope.projectId, scope.workflowId, scope.runId) : runHref)
  const openRequirement = useCallback((nodeId: string, quote: string) => {
    setPendingHighlight({ nodeId, quote })
    onNavigate(nodeHref(nodeId))
  }, [onNavigate, nodeHref])
  const openFile = useCallback((nodeId: string, path: string) => {
    setPendingFile({ nodeId, path })
    onNavigate(nodeHref(nodeId))
  }, [onNavigate, nodeHref])

  const onTabKey = (event: KeyboardEvent<HTMLButtonElement>) => {
    const index = TABS.findIndex(candidate => candidate.id === tab)
    let next: number | null = null
    if (event.key === 'ArrowRight' || event.key === 'ArrowDown') next = (index + 1) % TABS.length
    else if (event.key === 'ArrowLeft' || event.key === 'ArrowUp') next = (index - 1 + TABS.length) % TABS.length
    else if (event.key === 'Home') next = 0
    else if (event.key === 'End') next = TABS.length - 1
    if (next === null) return
    event.preventDefault()
    onNavigate(tabHref(TABS[next].id))
    event.currentTarget.parentElement?.querySelector<HTMLButtonElement>(`[data-testid="${TABS[next].testId}"]`)?.focus()
  }

  // Selecting a step opens its page at the top with the focus on its heading; coming back focuses the step's row again.
  const shownNode = useRef(selectedNodeId)
  useEffect(() => {
    const previous = shownNode.current
    shownNode.current = selectedNodeId
    if (previous === selectedNodeId) return
    if (selectedNodeId !== null) {
      window.scrollTo(0, 0)
      document.getElementById('node-detail-title')?.focus({ preventScroll: true })
    } else if (previous !== null) {
      document.querySelector<HTMLElement>(`[data-testid="run-node-list"] [data-node-id="${CSS.escape(previous)}"] a`)?.focus()
    }
  }, [selectedNodeId])

  // While a question, a pane or an approval waits on the operator, the tab title says so (docs/PRD_VIEWER_UX.md 6.4).
  const waiting = attention?.top != null
  useEffect(() => {
    if (!waiting) return
    const title = document.title
    document.title = `? Waiting · ${summary.run_id} — ${title}`
    return () => { document.title = title }
  }, [waiting, summary.run_id])

  // The polite announcer speaks the Now headline only when the situation changes, never on a poll that changed nothing.
  const situation = now?.situation ?? null
  const spoken = useRef<string | null>(null)
  useEffect(() => {
    if (now === null) return
    const previous = spoken.current
    spoken.current = now.situation
    if (previous === null || previous === now.situation) return
    const format = { clock: (at: string) => formatClock(at, { zone, reference: runStart }), ago: formatAgo, span: formatSpan }
    onAnnounce(`Now: ${textToString(withoutGlyph(now.headline, now.glyph), Date.now(), format)}`)
    // Only a change of situation speaks; the headline's clock and ages change every second.
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [situation])

  const tabs = (
    <div className="tabs run-tabs" role="tablist" aria-label="Run views">
      {TABS.map(candidate => (
        <button
          key={candidate.id}
          type="button"
          role="tab"
          id={`run-tab-${candidate.id}`}
          className="tab"
          aria-selected={tab === candidate.id}
          aria-controls={`run-panel-${candidate.id}`}
          tabIndex={tab === candidate.id ? 0 : -1}
          data-testid={candidate.testId}
          onClick={() => { if (tab !== candidate.id || selectedNodeId !== null) onNavigate(tabHref(candidate.id)) }}
          onKeyDown={onTabKey}
        >
          {candidate.label}
        </button>
      ))}
    </div>
  )

  return (
    <div className="run-view" data-testid="run-view" data-run-id={summary.run_id} data-run-status={summary.status}>
      {selectedNodeId === null ? (
        <>
          <RunHeader detail={detail} inputs={inputs} onRetryInputs={reloadInputs} current={current} freshness={freshness} timeline={timeline} clock={clock} />
          {events.status === 'error'
            ? <ErrorPanel error={events.error} what="The run's events" onRetry={reloadEvents}><span>Without them the situation and the next step cannot be read.</span></ErrorPanel>
            : <NowBanner now={now} clock={clock} focusHref={now?.focus ? nodeHref(now.focus.node_id) : null} onNavigate={onNavigate} />}
          <LanesLine lines={lanes} />
        </>
      ) : (
        <RunBar detail={detail} now={now} clock={clock} runHref={runHref} freshness={freshness} onNavigate={onNavigate} />
      )}

      <div className="run-views">
      {tabs}

      {tab === 'assignment' ? (
        <AssignmentPanel scope={scope} inputs={inputs} onRetry={reloadInputs} onNavigate={onNavigate} panelId="run-panel-assignment" tabId="run-tab-assignment" />
      ) : (
        <div role="tabpanel" id="run-panel-run" aria-labelledby="run-tab-run" className="run-body">
          {selectedNodeId === null ? (
            <>
              <section className="run-graph" aria-label="Pinned graph">
                <WorkflowGraph title={`Pinned definition graph of run ${summary.run_id}`} nodes={graphNodes} selectedId={null} onSelect={nodeId => onNavigate(nodeHref(nodeId))} />
              </section>
              <StepsTable rows={rows} timeline={timeline} now={clock} live={summary.status === 'running' || summary.status === 'awaiting_approval'} nodeHref={nodeHref} onNavigate={onNavigate} />
              {(events.status === 'loading' || events.status === 'idle') && <LoadingPanel>Loading the run's events…</LoadingPanel>}
              {timeline && <Activity timeline={timeline} labels={labels} nodeHref={nodeHref} onNavigate={onNavigate} />}
            </>
          ) : (
            <>
              <StepStrip detail={detail} rows={rows} current={selectedNodeId} runHref={runHref} nodeHref={nodeHref} onNavigate={onNavigate} />
              <div className="run-node-area">
                {(selectedDefinition === null || selectedState === null) && (
                  <div className="projects-error" role="alert" data-testid="node-missing">
                    <p>Node <code>{selectedNodeId}</code> is not part of this run's pinned definition.</p>
                    <p><AppLink href={runHref} onNavigate={onNavigate}>Back to the run</AppLink></p>
                  </div>
                )}
                {selectedDefinition !== null && selectedState !== null && (
                  <NodeDetail
                    key={selectedNodeId}
                    scope={scope}
                    definition={selectedDefinition}
                    definitionNodes={definition.nodes}
                    snapshotNodes={snapshot.nodes}
                    node={selectedState}
                    events={events}
                    onRetryEvents={reloadEvents}
                    inputs={inputs}
                    onRetryInputs={reloadInputs}
                    refreshToken={refreshToken}
                    onNavigate={onNavigate}
                    highlight={highlight}
                    onHighlightApplied={clearHighlight}
                    onOpenRequirement={openRequirement}
                    fileFocus={fileFocus}
                    onFileFocusApplied={clearFile}
                    onOpenFile={openFile}
                  />
                )}
              </div>
            </>
          )}
        </div>
      )}
      </div>
    </div>
  )
}

import { useLayoutEffect, useRef, useState, type ReactNode } from 'react'
import type { LaneLine, Now, Text, TextPart } from '../../contracts/projects/triage.ts'
import { CommandBlock } from './CommandBlock.tsx'
import { AppLink } from './panels.tsx'
import { withoutGlyph } from './steps.ts'
import { Time } from './Time.tsx'
import { formatAgo, formatSpan, utcTitle } from './time.ts'

/** How many lanes the lanes line lists before the rest move behind "+n more". */
const LANES_SHOWN = 3

/** One part of the triage model's rich text: a clock as `<Time>`, ages, durations and deadlines against the page's ticking clock. */
function Part({ part, now }: { part: TextPart; now: number }): ReactNode {
  if (typeof part === 'string') return part
  switch (part.kind) {
    case 'clock': return <>{part.inferred ? '≈' : ''}<Time iso={part.at} /></>
    case 'ago': return <time dateTime={part.at} title={utcTitle(part.at)}>{formatAgo(part.at, now)}</time>
    case 'span': return `${part.inferred ? '≈' : ''}${formatSpan(part.ms)}`
    case 'elapsed': return formatSpan(Math.max(0, now - Date.parse(part.from)))
    case 'left': return formatSpan(Math.max(0, Date.parse(part.until) - now))
  }
}

/** Renders the triage model's rich text (headlines and reasons) in the viewer's zone and against its clock. */
export function RichText({ text, now }: { text: Text; now: number }) {
  return <>{text.map((part, index) => <Part key={index} part={part} now={now} />)}</>
}

/** The reason, clamped to two lines with a More toggle once it is longer; `after` (the focus link) stays outside the clamp. */
function Reason({ children, after }: { children: ReactNode; after: ReactNode }) {
  const paragraph = useRef<HTMLParagraphElement>(null)
  const [open, setOpen] = useState(false)
  const [clamped, setClamped] = useState(false)
  // Measured after every change of the text: only an overflowing reason gets a More toggle.
  useLayoutEffect(() => {
    const element = paragraph.current
    if (element && !open) setClamped(element.scrollHeight > element.clientHeight + 1)
  }, [open, children])
  return (
    <div className="run-now-reason-row">
      <p ref={paragraph} className={open ? 'run-now-reason' : 'run-now-reason is-clamped'} data-testid="now-reason">{children}</p>
      {(clamped || open) && (
        <button type="button" className="button button-small run-now-more" aria-expanded={open} onClick={() => setOpen(previous => !previous)}>{open ? 'Less' : 'More'}</button>
      )}
      {after}
    </div>
  )
}

type Props = {
  /** Null while the events, inputs, review or the lane results the rules read are still loading. */
  now: Now | null
  clock: number
  /** The focus step's page, for its "Open" link; null when there is no focus. */
  focusHref: string | null
  onNavigate: (pathname: string) => void
}

/**
 * The Now banner (docs/PRD_VIEWER_UX.md 4.2, 6.2): where the run is or stopped, why, since when, and what to type next,
 * derived from the run's current state only (`deriveNow`). `data-situation` names the matched rule. It is not a live
 * region: the page announces only a change of situation.
 */
export function NowBanner({ now, clock, focusHref, onNavigate }: Props) {
  if (now === null) {
    return (
      <section className="run-now run-now-loading" data-testid="run-now" aria-busy="true" aria-labelledby="run-now-title">
        <h3 id="run-now-title" className="visually-hidden">Now</h3>
        <p className="run-now-headline projects-muted">Reading the run's events and results…</p>
      </section>
    )
  }
  const open = now.focus && focusHref
    ? <AppLink href={focusHref} onNavigate={onNavigate} className="run-now-open">Open {now.focus.label} ›</AppLink>
    : null
  return (
    <section className={`run-now run-now-${now.tone}`} data-testid="run-now" data-situation={now.situation} aria-labelledby="run-now-title">
      <h3 id="run-now-title" className="visually-hidden">Now</h3>
      <p className="run-now-headline" data-testid="now-headline">
        <span className="run-now-glyph" aria-hidden="true">{now.glyph}</span>
        <span><RichText text={withoutGlyph(now.headline, now.glyph)} now={clock} /></span>
        {now.reason === null && open}
      </p>
      {now.reason !== null && <Reason after={open}><RichText text={now.reason} now={clock} /></Reason>}
      <CommandBlock next={now.next} />
    </section>
  )
}

/**
 * The lanes line (docs/PRD_VIEWER_UX.md 4.2), for runs with two or more lanes: one line per lane with its worker, verify and
 * candidate steps and no durations, the Steps table's job.
 */
export function LanesLine({ lines }: { lines: LaneLine[] }) {
  if (lines.length < 2) return null
  const item = (line: LaneLine) => (
    <li key={line.lane} data-lane={line.lane}>
      <span className="run-lane-name">{line.lane}</span>
      <span className="run-lane-steps">
        {line.steps.map((step, index) => (
          <span key={step.node_id} className={`run-lane-step status-text-${step.status}`}>{index > 0 ? ' · ' : ''}{step.text}</span>
        ))}
      </span>
    </li>
  )
  return (
    <section className="run-lanes" data-testid="run-lanes" aria-labelledby="run-lanes-title">
      <h3 id="run-lanes-title" className="run-lanes-title">Lanes</h3>
      <ul className="run-lanes-list">{lines.slice(0, LANES_SHOWN).map(item)}</ul>
      {lines.length > LANES_SHOWN && (
        <details className="run-lanes-more">
          <summary>+{lines.length - LANES_SHOWN} more</summary>
          <ul className="run-lanes-list">{lines.slice(LANES_SHOWN).map(item)}</ul>
        </details>
      )}
    </section>
  )
}
import { useEffect, useRef, useState } from 'react'
import { COMMAND_CAPTION, COMMAND_LEGEND, type NextStep, type RunbookRef } from '../../contracts/projects/triage.ts'

/** How long "Copied" stays beside a Copy button. */
const COPIED_MS = 2500

const runbookText = (ref: RunbookRef) => ref.topic ?? ref.section
const runbookTitle = (refs: RunbookRef[]) => refs.map(ref => `RUNBOOK › ${ref.section}${ref.topic ? ` › ${ref.topic}` : ''}`).join('\n')

/** Selects a command's text, so it can be copied by hand where the clipboard API is unavailable (a non-secure http origin). */
function select(element: HTMLElement) {
  const selection = element.ownerDocument.getSelection()
  if (!selection) return
  const range = element.ownerDocument.createRange()
  range.selectNodeContents(element)
  selection.removeAllRanges()
  selection.addRange(range)
}

/**
 * One copyable command (docs/PRD_VIEWER_UX.md 6.1): the command lives in a `<code>` outside any button, so the viewer offers
 * text to copy, never an action. Copy writes it to the clipboard, or selects it when the clipboard API is unavailable.
 */
function CommandLine({ text, caption }: { text: string; caption?: string }) {
  const code = useRef<HTMLElement>(null)
  const [outcome, setOutcome] = useState<'copied' | 'selected' | null>(null)
  useEffect(() => {
    if (outcome === null) return
    const timer = window.setTimeout(() => setOutcome(null), COPIED_MS)
    return () => window.clearTimeout(timer)
  }, [outcome])
  const copy = async () => {
    try {
      if (!window.isSecureContext || !navigator.clipboard) throw new Error('The clipboard is unavailable.')
      await navigator.clipboard.writeText(text)
      setOutcome('copied')
    } catch {
      if (code.current) select(code.current)
      setOutcome('selected')
    }
  }
  return (
    <div className="command-step-body">
      {caption && <span className="command-step-caption">{caption}</span>}
      <span className="command-line"><span className="command-prompt" aria-hidden="true">$ </span><code ref={code} data-testid="now-command">{text}</code></span>
      <button type="button" className="button button-small command-copy" data-testid="copy-command" aria-label="Copy command" onClick={() => void copy()}>Copy</button>
      <span className="command-copied" role="status">{outcome === 'copied' ? 'Copied' : outcome === 'selected' ? 'Selected: copy it with Ctrl+C' : ''}</span>
    </div>
  )
}

/**
 * The "Likely next step" block (docs/PRD_VIEWER_UX.md 6.1): the step's label and its RUNBOOK section, the `$PY/$RUN` legend,
 * numbered steps where each command has its own Copy button and a text step is plain text, and the one-line honesty
 * caption. A step that needs nothing says so and shows no command unless one is optional.
 */
export function CommandBlock({ next }: { next: NextStep }) {
  const commands = next.steps.some(step => step.kind === 'command')
  const lead = next.action === 'required' ? 'Likely next step' : null
  return (
    <div className="command-block" data-testid="now-next" data-action={next.action}>
      <div className="command-label">
        {lead && <strong>{lead}</strong>}
        <span>{lead ? `— ${next.label.charAt(0).toLowerCase()}${next.label.slice(1)}` : next.label}</span>
        {next.runbook.length > 0 && <span className="command-runbook" title={runbookTitle(next.runbook)}>RUNBOOK “{runbookText(next.runbook[0])}”</span>}
        {commands && (
          <details className="command-legend" data-testid="command-legend">
            <summary>$PY/$RUN</summary>
            <span className="command-legend-text">{COMMAND_LEGEND}</span>
          </details>
        )}
      </div>
      {next.steps.length > 0 && (
        <ol className="command-steps">
          {next.steps.map((step, index) => (
            <li key={index} className="command-step" data-testid="now-step" data-kind={step.kind}>
              {step.kind === 'command' ? <CommandLine text={step.text} caption={step.caption} /> : <div className="command-step-body"><span className="command-prose">{step.text}</span></div>}
            </li>
          ))}
        </ol>
      )}
      {next.caveat && <p className="command-caveat">{next.caveat}</p>}
      {commands && <p className="command-caption">{COMMAND_CAPTION}</p>}
    </div>
  )
}

/**
 * The run page's Steps model (docs/PRD_VIEWER_UX.md 4.2, 5.3): one row per step of the pinned definition, in definition
 * order, read from the triage timeline. A row says when the step first started, how long it took from there to its last
 * verdict (to now while it runs), its attempt, the marks of its attempts in time order (✗ failed, ? ended without a record,
 * ⚑ the controller's diagnosis, ⚒ an operator repair, ✓ passed), its outcome and whether it waits on the operator. Also
 * the time axis of the Steps bars, which turns silences over 30 minutes into short breaks, and the step strip's labels.
 * Pure, so the Steps table, the step strip and the unit tests read the same rows.
 */
import type { RunDetail } from './api.ts'
import type { AttentionKind, Instant, NodeStatus, RunAttention, Span, SpanStatus, Text, Timeline } from '../../contracts/projects/triage.ts'

type DefinitionNode = RunDetail['definition']['nodes'][number]

export type StepRow = {
  node_id: string
  label: string
  kind: DefinitionNode['kind']
  /** The served status (`data-status`). */
  status: NodeStatus
  /** The status to show: a retry that runs while its node still reads failed is shown running. */
  shown: NodeStatus
  /** The latest attempt, 0 when the step never started. */
  attempt: number
  spans: Span[]
  /** The first attempt's start; null when nothing recorded one. */
  start: Instant | null
  /** The last verdict; null while the step runs or when none was recorded. */
  end: Instant | null
  /** From the start to the end (to now while the step runs); null when either is unknown. */
  ms: number | null
  live: boolean
  /** A start or an end was inferred rather than recorded: shown with `≈`, its source in the tooltip. */
  inferred: boolean
  /** The attempt marks in time order, empty for a single attempt with nothing to mark. */
  marks: string
  outcome: string
  attention: AttentionKind | null
}

/** A status as one glyph; colour never carries it alone (PRD_VIEWER_UX section 10). */
export const STATUS_GLYPH: Record<NodeStatus, string> = { pending: '○', running: '●', awaiting_approval: '?', paused: '‖', succeeded: '✓', failed: '✗', cancelled: '○' }
const SPAN_MARK: Record<SpanStatus, string> = { ...STATUS_GLYPH, no_record: '?' }
const MARKER_MARK = { diagnosis: '⚑', repair: '⚒' } as const

const ms = (instant: Instant) => Date.parse(instant.at)

export function stepRows(detail: RunDetail, timeline: Timeline, { now, attention }: { now: number; attention?: RunAttention }): StepRow[] {
  const snapshot = new Map(detail.snapshot.nodes.map(node => [node.node_id, node]))
  return detail.definition.nodes.map(node => {
    const status = snapshot.get(node.node_id)?.status ?? 'pending'
    const spans = timeline.byNode.get(node.node_id) ?? []
    const last = spans.at(-1)
    const live = spans.some(span => span.live)
    const starts = spans.flatMap(span => span.start ? [span.start] : [])
    const ends = spans.flatMap(span => span.end ? [span.end] : [])
    const start = starts.reduce<Instant | null>((first, instant) => first === null || ms(instant) < ms(first) ? instant : first, null)
    const end = live ? null : ends.reduce<Instant | null>((latest, instant) => latest === null || ms(instant) >= ms(latest) ? instant : latest, null)
    const finish = end ? ms(end) : live ? now : null
    const markers = timeline.markers.filter(marker => (marker.kind === 'diagnosis' || marker.kind === 'repair') && marker.node_id === node.node_id)
    const marks = spans.length > 1 || markers.length > 0
      ? [
        ...spans.map(span => ({ at: span.end?.at ?? span.start?.at ?? '', mark: span.live ? STATUS_GLYPH.running : SPAN_MARK[span.status] })),
        ...markers.map(marker => ({ at: marker.at, mark: MARKER_MARK[marker.kind as keyof typeof MARKER_MARK] })),
      ].sort((a, b) => Date.parse(a.at) - Date.parse(b.at)).map(item => item.mark).join('')
      : ''
    // The step's latest state: a status row that closed no attempt (a repair note, a resumed step) is newer than the last verdict.
    const settled = spans.reduce((latest, span) => Math.max(latest, Date.parse(span.end?.at ?? span.start?.at ?? '') || 0), 0)
    const update = timeline.activity.filter(row => row.node_id === node.node_id && row.kind === 'update' && row.status !== null && row.marker === null).at(-1)
    let outcome: string
    if (update && Date.parse(update.at) > settled) outcome = update.text
    else if (last?.outcome) outcome = node.node_id === 'candidate' && last.lane ? `${last.lane}: ${last.outcome}` : last.outcome
    else outcome = status === 'pending' ? 'not started' : `${status.replace('_', ' ')} · no event recorded`
    return {
      node_id: node.node_id, label: node.label, kind: node.kind, status, shown: live ? 'running' : status,
      attempt: status === 'pending' ? 0 : Math.max(snapshot.get(node.node_id)?.attempt ?? 0, last?.attempt ?? 0),
      spans, start, end, ms: start && finish !== null ? Math.max(0, finish - ms(start)) : null, live,
      inferred: spans.some(span => span.start?.source === 'inferred' || span.end?.source === 'inferred'),
      marks, outcome, attention: attention?.nodes.get(node.node_id)?.kind ?? null,
    }
  })
}

/** A silence with no step working that lasts longer than this becomes a break on the time axis (5.2 rule 6). */
export const AXIS_BREAK_MS = 30 * 60_000
/** How much time a break keeps on the axis, so it stays visible without squashing the steps around it. */
const BREAK_SHOWN_MS = 2 * 60_000

export type TimeAxis = {
  from: number
  to: number
  /** Where an instant sits on the axis, from 0 (the run's start) to 1 (its end, or now); outside values are clamped. */
  position(at: number): number
  /** The silences shown as breaks: where each starts on the axis and how long it really was. */
  breaks: { at: number; ms: number }[]
}

/** The Steps bars' time axis from `from` to `to`; `busy` are the steps' working intervals (epoch milliseconds). */
export function timeAxis(from: number, to: number, busy: readonly { start: number; end: number }[]): TimeAxis {
  const clamp = (at: number) => Math.min(to, Math.max(from, at))
  const merged: { start: number; end: number }[] = []
  for (const interval of busy.map(item => ({ start: clamp(item.start), end: clamp(item.end) })).filter(item => item.end >= item.start).sort((a, b) => a.start - b.start)) {
    const previous = merged.at(-1)
    if (previous && interval.start <= previous.end) previous.end = Math.max(previous.end, interval.end)
    else merged.push({ ...interval })
  }
  const silences: { start: number; end: number }[] = []
  let cursor = from
  for (const interval of merged) {
    if (interval.start - cursor > AXIS_BREAK_MS) silences.push({ start: cursor, end: interval.start })
    cursor = Math.max(cursor, interval.end)
  }
  if (to - cursor > AXIS_BREAK_MS) silences.push({ start: cursor, end: to })
  // Axis time: real time minus what each break leaves out; inside a break, its shown length is spread evenly.
  const axisTime = (at: number) => {
    let value = at - from
    for (const silence of silences) {
      const length = silence.end - silence.start
      if (at >= silence.end) value -= length - BREAK_SHOWN_MS
      else if (at > silence.start) value -= (at - silence.start) * (1 - BREAK_SHOWN_MS / length)
    }
    return value
  }
  const total = Math.max(1, axisTime(to))
  const position = (at: number) => Math.min(1, Math.max(0, axisTime(clamp(at)) / total))
  return { from, to, position, breaks: silences.map(silence => ({ at: position(silence.start), ms: silence.end - silence.start })) }
}

const FIXED_LABELS: Record<string, string> = { handoff: 'Freeze', candidate: 'Candidate', review: 'Review', approval: 'Approval', integrate: 'Integrate', challenge: 'Challenge' }

/** The step strip's short name of a step: "Launch game", "Verify game", "Freeze", "Candidate"; anything else keeps its label. */
export function shortStepLabel(node: { node_id: string; label: string }): string {
  if (node.node_id.startsWith('launch_')) return `Launch ${node.node_id.slice('launch_'.length)}`
  if (node.node_id.startsWith('verify_')) return `Verify ${node.node_id.slice('verify_'.length)}`
  return FIXED_LABELS[node.node_id] ?? node.label
}

/** A duration for the step strip: "46s", "28m", "1h05m". */
export function formatShortSpan(duration: number): string {
  const seconds = Math.max(0, Math.round(duration / 1000))
  if (seconds < 60) return `${seconds}s`
  const minutes = Math.floor(seconds / 60)
  if (minutes < 60) return `${minutes}m`
  return `${Math.floor(minutes / 60)}h${String(minutes % 60).padStart(2, '0')}m`
}

/** A Now headline without its leading status glyph, which the banner shows apart and hides from screen readers. */
export function withoutGlyph(text: Text, glyph: string): Text {
  const [first, ...rest] = text
  return typeof first === 'string' && first.startsWith(`${glyph} `) ? [first.slice(glyph.length + 1), ...rest] : text
}
import { useMemo, useState } from 'react'
import type { ActivityRow, MarkerKind, Timeline } from '../../contracts/projects/triage.ts'
import { AppLink } from './panels.tsx'
import { STATUS_LABEL } from './status.ts'
import { STATUS_GLYPH, timeAxis, type StepRow, type TimeAxis } from './steps.ts'
import { Time } from './Time.tsx'
import { formatSpan } from './time.ts'
import { useTimeZone } from './useNow.ts'

/** Where the Activity order is remembered in this browser; the page works the same without it. */
export const ACTIVITY_ORDER_STORAGE_KEY = 'mdm.projects.activityOrder'

function readNewestFirst(): boolean {
  try {
    return window.localStorage.getItem(ACTIVITY_ORDER_STORAGE_KEY) === 'newest'
  } catch {
    return false
  }
}

function rememberNewestFirst(newest: boolean) {
  try {
    window.localStorage.setItem(ACTIVITY_ORDER_STORAGE_KEY, newest ? 'newest' : 'oldest')
  } catch {
    // Not remembered; the order still switches.
  }
}

const sourceNote = (row: StepRow) => [row.start?.note ?? (row.start ? `start from ${row.start.source}` : null), row.end?.note ?? (row.end ? `end from ${row.end.source}` : null)]
  .filter(Boolean).join('; ')

/** The Steps bar of one row: each attempt from its start to its end (to now while it runs) on the run's time axis. */
function Bar({ row, axis, now }: { row: StepRow; axis: TimeAxis; now: number }) {
  return (
    <span className="step-bar-track">
      {row.spans.flatMap((span, index) => {
        const start = span.start ?? span.end
        if (!start) return []
        const end = span.end ?? (span.live ? { at: new Date(now).toISOString() } : start)
        const left = axis.position(Date.parse(start.at))
        const right = axis.position(Date.parse(end.at))
        const status = span.live ? 'running' : span.status
        return [<span key={index} className={`step-bar-segment status-fill-${status}`} style={{ left: `${left * 100}%`, width: `${Math.max(0, right - left) * 100}%` }} />]
      })}
      {axis.breaks.map(item => <span key={item.at} className="step-bar-break" style={{ left: `${item.at * 100}%` }} />)}
    </span>
  )
}

type StepsProps = {
  rows: StepRow[]
  timeline: Timeline | null
  now: number
  /** The run can still move by itself (running or awaiting a decision): its axis runs to now, else to its last activity. */
  live: boolean
  nodeHref: (nodeId: string) => string
  onNavigate: (pathname: string) => void
}

/**
 * The Steps table (docs/PRD_VIEWER_UX.md 4.2, `run-node-list`): one row per step with when it started, how long it took, its
 * attempts and their marks, its outcome and a bar on the run's time axis. Each row's step link opens the node page; the
 * bar is decoration, its times are in the text cells. Inferred times carry `≈`, their source in the tooltip.
 */
export function StepsTable({ rows, timeline, now, live, nodeHref, onNavigate }: StepsProps) {
  const [zone] = useTimeZone()
  const from = timeline ? Math.min(Date.parse(timeline.runStart.at), ...rows.flatMap(row => row.start ? [Date.parse(row.start.at)] : [])) : null
  const ends = rows.flatMap(row => row.end ? [Date.parse(row.end.at)] : [])
  const to = timeline === null ? null
    : timeline.runEnd ? Date.parse(timeline.runEnd.at)
      : live ? Math.max(now, ...ends)
        : Math.max(timeline.lastActivity ? Date.parse(timeline.lastActivity.at) : 0, ...ends)
  const busy = rows.flatMap(row => row.spans.flatMap(span => {
    const start = span.start ?? span.end
    if (!start) return []
    return [{ start: Date.parse(start.at), end: span.end ? Date.parse(span.end.at) : span.live ? now : Date.parse(start.at) }]
  }))
  const axis = from !== null && to !== null && to > from ? timeAxis(from, to, busy) : null
  return (
    <section className="run-steps" aria-labelledby="run-steps-title">
      <h3 id="run-steps-title" className="visually-hidden">Steps</h3>
      <table className="steps-table" data-testid="run-node-list" role="table" aria-labelledby="run-steps-title">
        <caption className="steps-hint" data-testid="node-hint">Select a step to open its evidence. ≈ marks a time no event recorded: it is inferred (hover for the source).</caption>
        <thead role="rowgroup">
          <tr role="row">
            <th scope="col" role="columnheader" className="step-name">Step</th>
            <th scope="col" role="columnheader" className="step-started">Started{zone === 'utc' ? ' (UTC)' : ''}</th>
            <th scope="col" role="columnheader" className="step-took">Took</th>
            <th scope="col" role="columnheader" className="step-attempts">Attempts</th>
            <th scope="col" role="columnheader" className="step-outcome">Outcome</th>
            <th scope="col" role="columnheader" className="step-bar">
              {axis && timeline ? (
                <span className="step-axis" aria-hidden="true">
                  <Time iso={new Date(axis.from).toISOString()} />
                  <span className="step-axis-rule" title={axis.breaks.length ? `Silences over 30 minutes are shortened: ${axis.breaks.map(item => formatSpan(item.ms)).join(', ')}` : undefined}>
                    {formatSpan(axis.to - axis.from)}{axis.breaks.length > 0 ? ` · ${axis.breaks.length} ${axis.breaks.length === 1 ? 'break' : 'breaks'}` : ''}
                  </span>
                  <Time iso={new Date(axis.to).toISOString()} />
                </span>
              ) : <span className="visually-hidden">Timeline</span>}
            </th>
          </tr>
        </thead>
        <tbody role="rowgroup">
          {rows.map(row => {
            const glyph = row.attention ? '?' : STATUS_GLYPH[row.shown]
            const note = sourceNote(row)
            return (
              <tr key={row.node_id} role="row" className={`step-row status-row-${row.shown}`} data-node-id={row.node_id} data-status={row.status} data-attention={row.attention ?? undefined}>
                <th scope="row" role="rowheader" className="step-name">
                  <AppLink href={nodeHref(row.node_id)} onNavigate={onNavigate} className="step-link" title={`${row.label}: ${STATUS_LABEL[row.shown].toLowerCase()}${row.attention ? ', waits on you' : ''}`}>
                    <span className={`step-glyph status-text-${row.shown}`} aria-hidden="true">{glyph}</span>
                    <span className="step-label">{row.label}</span>
                  </AppLink>
                </th>
                <td role="cell" className="step-started" title={row.start?.note ?? undefined}>{row.start ? <>{row.start.source === 'inferred' ? '≈' : ''}<Time iso={row.start.at} /></> : '—'}</td>
                <td role="cell" className="step-took" title={note || undefined}>{row.ms === null ? '—' : `${row.inferred ? '≈' : ''}${formatSpan(row.ms)}`}</td>
                <td role="cell" className="step-attempts">{row.attempt === 0 ? '—' : `attempt ${row.attempt}`}{row.marks && <> · <span className="step-marks">{row.marks}</span></>}</td>
                <td role="cell" className="step-outcome" title={row.outcome}>{row.outcome}</td>
                <td role="cell" className="step-bar" aria-hidden="true">{axis && <Bar row={row} axis={axis} now={now} />}</td>
              </tr>
            )
          })}
        </tbody>
      </table>
    </section>
  )
}

const MARKER_WHO: Partial<Record<MarkerKind, string>> = { diagnosis: '⚑ Controller', repair: '⚒ Operator', question: '? Question', answer: 'Answer' }
const STATUS_WORD: Record<string, string> = { failed: 'failed', succeeded: 'succeeded', paused: 'paused', cancelled: 'cancelled', no_record: 'ended without a record' }

type ActivityProps = {
  timeline: Timeline
  labels: ReadonlyMap<string, string>
  nodeHref: (nodeId: string) => string
  onNavigate: (pathname: string) => void
}

/**
 * Activity (docs/PRD_VIEWER_UX.md 4.2, `run-timeline`): the run's history as rows, oldest first unless the reader chose
 * newest first (remembered). Node-less controller rows, the diagnosis and the repair included, are shown like any other; only
 * the controller's PID checkpoints sit behind "Controller log (n)". Silences are rows of text. An attempt row opens its node.
 */
export function Activity({ timeline, labels, nodeHref, onNavigate }: ActivityProps) {
  const [zone] = useTimeZone()
  const [newestFirst, setNewestFirst] = useState(readNewestFirst)
  const [showLog, setShowLog] = useState(false)
  const logCount = timeline.activity.filter(row => row.controller_log).length
  const rows = useMemo(() => {
    const shown = timeline.activity.filter(row => showLog || !row.controller_log)
    return newestFirst ? [...shown].reverse() : shown
  }, [timeline, showLog, newestFirst])
  const attempts = (nodeId: string) => timeline.byNode.get(nodeId)?.length ?? 0

  const who = (row: ActivityRow) => {
    if (row.marker && MARKER_WHO[row.marker]) return MARKER_WHO[row.marker]!
    if (row.node_id === null || row.marker === 'controller_start' || row.marker === 'controller_error' || row.marker === 'controller_blocked' || row.marker === 'interrupted') return 'Controller'
    return labels.get(row.node_id) ?? row.node_id
  }
  const text = (row: ActivityRow) => {
    let value = row.text
    if (row.kind === 'end' && row.attempt !== null && row.node_id !== null && attempts(row.node_id) > 1 && !/^attempt \d+/i.test(value)) {
      value = `attempt ${row.attempt} ${STATUS_WORD[row.status ?? ''] ?? ''} · ${value}`.replace(/ {2}/g, ' ')
    }
    if (row.kind === 'end' && row.ms !== null) value += ` · ${row.inferred ? '≈' : ''}${formatSpan(row.ms)}`
    return value
  }

  return (
    <section className="run-activity" data-testid="run-timeline" aria-labelledby="run-activity-title">
      <div className="activity-head">
        <h3 id="run-activity-title">Activity{zone === 'utc' ? ' (UTC)' : ''}</h3>
        <span className="projects-muted">{newestFirst ? 'newest first' : 'oldest first'}</span>
        <button
          type="button"
          className="button button-small"
          aria-pressed={newestFirst}
          data-testid="activity-order"
          onClick={() => setNewestFirst(previous => { rememberNewestFirst(!previous); return !previous })}
        >
          Newest first
        </button>
        {logCount > 0 && (
          <button type="button" className="button button-small" aria-pressed={showLog} data-testid="activity-controller-log" onClick={() => setShowLog(previous => !previous)}>
            Controller log ({logCount})
          </button>
        )}
      </div>
      <ol className="activity-list">
        {rows.map((row, index) => {
          if (row.kind === 'gap') {
            return (
              <li key={`gap-${row.at}-${index}`} className="activity-row activity-gap" data-kind="gap" data-gap={row.gap?.kind}>
                <span className="activity-gap-text">┆ {row.text} {row.ms === null ? '' : formatSpan(row.ms)}</span>
              </li>
            )
          }
          const status = row.kind === 'end' ? row.status : null
          const link = row.kind === 'end' && row.node_id !== null && labels.has(row.node_id) && (row.status === 'failed' || attempts(row.node_id) > 1)
          return (
            <li
              key={`${row.sequence ?? row.at}-${row.kind}-${index}`}
              className={`activity-row${row.controller_log ? ' activity-log' : ''}`}
              data-kind={row.kind}
              data-marker={row.marker ?? undefined}
              data-node-id={row.node_id ?? undefined}
              data-status={status ?? undefined}
            >
              <span className="activity-time">{row.inferred ? '≈' : ''}<Time iso={row.at} seconds /></span>
              <span className="activity-who">{who(row)}</span>
              <span className="activity-text" title={row.raw && row.raw !== row.text ? `#${row.sequence ?? '—'}: ${row.raw}` : undefined}>
                {status && <span className={`activity-glyph status-text-${status === 'no_record' ? 'pending' : status}`} aria-hidden="true">{status === 'no_record' ? '?' : STATUS_GLYPH[status]} </span>}
                {text(row)}
              </span>
              {link && (
                <AppLink href={nodeHref(row.node_id!)} onNavigate={onNavigate} className="activity-open" aria-label={`Open ${labels.get(row.node_id!)}, attempt ${row.attempt ?? ''}`.trim()}>open ›</AppLink>
              )}
            </li>
          )
        })}
      </ol>
    </section>
  )
}

import { useLayoutEffect, useMemo, useRef, type CSSProperties } from 'react'
import type { RunDetail } from './api.ts'
import { layoutDag } from './dag.ts'
import { AppLink } from './panels.tsx'
import { STATUS_LABEL } from './status.ts'
import { formatShortSpan, shortStepLabel, STATUS_GLYPH, type StepRow } from './steps.ts'

type Props = {
  detail: RunDetail
  rows: StepRow[]
  current: string
  runHref: string
  nodeHref: (nodeId: string) => string
  onNavigate: (pathname: string) => void
}

/**
 * The sticky step strip of a node page (docs/PRD_VIEWER_UX.md 4.4, `run-node-list`): every step as a chip in the graph's
 * column order, lanes stacked within a column, the current one marked; then the previous and next step. It replaces the
 * graph on node pages, so the two never share a screen. On a phone it scrolls sideways inside itself, never the page.
 */
export function StepStrip({ detail, rows, current, runHref, nodeHref, onNavigate }: Props) {
  const list = useRef<HTMLOListElement>(null)
  const layout = useMemo(() => layoutDag(detail.definition.nodes), [detail.definition.nodes])
  const index = rows.findIndex(row => row.node_id === current)
  const previous = index > 0 ? rows[index - 1] : null
  const next = index >= 0 && index < rows.length - 1 ? rows[index + 1] : null

  // Keep the current chip in view inside the strip, without scrolling the page.
